package ru.neverland.mintcontracts.procurement;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;
import com.palmergames.bukkit.towny.object.Town;
import ru.neverland.core.*;
import ru.neverland.mintcontracts.api.BuildingProcurementApi;
import ru.neverland.mintcontracts.integration.TownyHook;
import ru.neverland.mintcontracts.model.*;
import ru.neverland.mintcontracts.service.*;

/** A UI submits requests only. Bank funding, immutable terms and publication remain provider-owned. */
public final class ProcurementService implements BuildingProcurementApi {
    private record Offer(String project,int level,String title,String fingerprint,String itemKey,String item,String name,int amount,long cents,long duration){
        Map<String,Object> view(){return Map.of("project",project,"targetLevel",level,"building",title,"itemKey",itemKey,"name",name,"amount",amount,"rewardCents",cents,"durationSeconds",duration,"reason","Поставка придёт на общий склад; условия после оплаты фиксируются");}
    }
    private final JavaPlugin plugin;private final TownyHook towns;private final ContractService contracts;private final ProcurementRepository repository;private final ProcurementAudit audit;private final BukkitTask pulse;
    private final Set<UUID> busy=ConcurrentHashMap.newKeySet();private final Set<CompletableFuture<?>> pending=ConcurrentHashMap.newKeySet();private volatile boolean closing;private CompletableFuture<Void> stopped;
    public ProcurementService(JavaPlugin plugin,TownyHook towns,ContractService contracts){this.plugin=plugin;this.towns=towns;this.contracts=contracts;repository=new ProcurementRepository(plugin.getDataFolder().toPath().resolve("procurement.sqlite"));audit=new ProcurementAudit(repository,row->AuditTrail.record(plugin,row),plugin.getLogger()::warning);pulse=SuiteScheduler.get().runTaskTimer(plugin,()->{if(repository.available())audit.flush();},100,100);repository.ready().whenComplete((v,e)->{if(e!=null)plugin.getLogger().warning("Закупки материалов недоступны; прежние контракты сохранены: "+e.getMessage());});}
    public ProcurementRepository repository(){return repository;}
    private void live(){if(closing||!plugin.isEnabled()||SuiteState.frozen(plugin.getName()))throw new IllegalArgumentException("Закупки приостановлены; сохранённые резервы не изменяются");}
    private Town mayor(Player player,UUID expected){live();Town town=towns.town(player);if(!player.hasPermission("mintcontracts.buildorders")||town==null||!town.isMayor(towns.resident(player))||expected!=null&&!town.getUUID().equals(expected))throw new IllegalArgumentException("Управлять закупкой может действующий мэр своего города");return town;}
    private void reader(Player player,ProcurementOrder order){live();if(player.hasPermission("mintcontracts.admin")||player.getUniqueId().equals(order.actor()))return;mayor(player,order.town());}
    private void newWork(){if(!plugin.getConfig().getBoolean("building-orders.enabled",true))throw new IllegalArgumentException("Новые закупки отключены; сохранённые оплаты можно сверить или вернуть");}
    private static Throwable cause(Throwable error){while(error.getCause()!=null&&(error instanceof CompletionException||error instanceof java.lang.reflect.InvocationTargetException))error=error.getCause();return error;}
    /** Player work uses the owning scheduler. Public completion always leaves SuiteState first. */
    @FunctionalInterface private interface PlayerWork<T>{CompletionStage<T> get()throws Exception;}
    private <T>CompletionStage<T> owner(Player player,PlayerWork<T> work){var result=new CompletableFuture<T>();pending.add(result);result.whenComplete((v,e)->pending.remove(result));if(closing||!plugin.isEnabled()){reply(result,null,new IllegalStateException("Закупки останавливаются"));return result;}try{var task=SuiteScheduler.entityLater(plugin,player,()->{try{live();if(!player.isOnline())throw new IllegalArgumentException("Игрок вышел; сохранённая смета доступна после входа");work.get().whenComplete((v,e)->reply(result,v,e));}catch(Throwable error){reply(result,null,error);}},()->reply(result,null,new IllegalStateException("Игрок вышел; резерв сохранён")),1);if(task.isCancelled())reply(result,null,new IllegalStateException("Закупки останавливаются"));}catch(Throwable error){reply(result,null,error);}return result;}
    private static <T>void reply(CompletableFuture<T> target,T value,Throwable error){CompletableFuture.runAsync(()->{if(error==null)target.complete(value);else target.completeExceptionally(cause(error));});}
    private <T>CompletionStage<T> serial(UUID id,Supplier<CompletionStage<T>> work){if(!busy.add(id))return CompletableFuture.failedFuture(new IllegalArgumentException("Эта закупка уже сохраняется; дождитесь ответа"));try{return work.get().whenComplete((v,e)->busy.remove(id));}catch(Throwable error){busy.remove(id);return CompletableFuture.failedFuture(error);}}
    private ApiServices.Connection bank(String capability){var link=ApiServices.connect("NeverLandTownyTreasuryPlus","ru.neverland.townytreasury.api.TownyTreasuryApi",1,capability,"debitStatus");if(!link.ready())throw new IllegalArgumentException("Подтверждённые операции казны временно недоступны; деньги не списываются повторно");return link;}
    @SuppressWarnings("unchecked")private Map<String,Object> bankStatus(UUID id)throws Exception{return Map.copyOf((Map<String,Object>)bank("debitStatus").invoke("debitStatus",new Class<?>[]{UUID.class},id));}
    @SuppressWarnings("unchecked")private CompletionStage<Map<String,Object>> requestDebit(ProcurementOrder r)throws Exception{return (CompletionStage<Map<String,Object>>)bank("requestDebit").invoke("requestDebit",new Class<?>[]{UUID.class,UUID.class,String.class,String.class,long.class,String.class,UUID.class,String.class},r.id(),r.town(),"infrastructure","contracts",r.cents(),r.bankReason(),r.actor(),plugin.getName());}
    @SuppressWarnings("unchecked")private CompletionStage<Map<String,Object>> requestRefund(ProcurementOrder r)throws Exception{return (CompletionStage<Map<String,Object>>)bank("requestRefund").invoke("requestRefund",new Class<?>[]{UUID.class,UUID.class,UUID.class,String.class,String.class},r.refundId(),r.id(),r.refundActor(),plugin.getName(),r.refundReason());}
    @SuppressWarnings("unchecked")private Map<String,Object> needs(UUID town,String project)throws Exception{return (Map<String,Object>)ApiServices.require("NeverLandTownyBuilds","ru.neverland.townybuilds.api.BuildingMaterialsApi","needs").invoke("needs",new Class<?>[]{UUID.class,String.class},town,project);}
    private static String hash(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(Exception error){throw new IllegalStateException(error);}}
    private static long number(Object value){try{return new java.math.BigDecimal(String.valueOf(value)).longValueExact();}catch(Exception error){throw new IllegalArgumentException("Неверное число в смете здания");}}
    private Offer offer(Map<String,Object> needs,Map<?,?> row,long promised,String fingerprint){String encoded=String.valueOf(row.get("item"));ItemStack sample=ContractCodec.item(encoded);if(sample==null||sample.getType().isAir()||sample.getAmount()!=1)throw new IllegalArgumentException("Предмет сметы требует проверки");long missing=Math.max(0,number(row.get("amount"))-promised);if(missing==0)return null;if(missing>1_000_000)throw new IllegalArgumentException("Количество поставки превышает предел контракта");String raw=plugin.getConfig().getString("building-orders.unit-rewards."+sample.getType().name(),plugin.getConfig().getString("building-orders.default-unit-reward","0.10"));long cents=Math.multiplyExact(BuildOrders.money(raw),missing),maximum=BuildOrders.money(plugin.getConfig().getString("building-orders.maximum-reward","50000.00"));if(cents>maximum)throw new IllegalArgumentException("Награда превышает предел закупки в настройках");long duration=plugin.getConfig().getLong("building-orders.duration-seconds",86400);if(duration<60||duration>31_536_000)throw new IllegalArgumentException("Неверный срок закупки");return new Offer(String.valueOf(needs.get("project")),Math.toIntExact(number(needs.get("targetLevel"))),String.valueOf(needs.get("title")),fingerprint,hash(encoded),encoded,String.valueOf(row.get("name")),Math.toIntExact(missing),cents,duration);}
    private CompletionStage<List<Offer>> offered(Player player,String project,UUID exclude){Town town=mayor(player,null);UUID city=town.getUUID();Set<UUID> activeIds=contracts.active(city).stream().map(ActiveContract::id).collect(java.util.stream.Collectors.toUnmodifiableSet());return repository.outstanding(city,project,activeIds).thenCompose(rows->owner(player,()->{
        mayor(player,city);newWork();if(!activeIds.equals(contracts.active(city).stream().map(ActiveContract::id).collect(java.util.stream.Collectors.toUnmodifiableSet())))throw new IllegalArgumentException("Городские контракты изменились; повторите расчёт");var needs=needs(city,project);var promised=new HashMap<String,Long>();var evidence=new ArrayList<String>();
        for(var row:rows){if(row.id().equals(exclude)||Set.of("PUBLISHED","SETTLED").contains(row.state())||row.level()!=number(needs.get("targetLevel")))continue;var active=contracts.find(city,row.id().toString());if(active!=null)continue;promised.merge(row.itemKey(),(long)row.amount(),Math::addExact);evidence.add(row.id()+":"+row.state()+":"+row.amount());}
        for(var contract:contracts.active(city)){var definition=contracts.definition(contract);if(definition==null||definition.type()!=ContractType.DELIVERY)continue;boolean sameLegacy=definition.id().startsWith("build_"+project+"_"+number(needs.get("targetLevel"))+"_");boolean sameNew=rows.stream().anyMatch(r->r.id().equals(contract.id())&&r.level()==number(needs.get("targetLevel")));if(!sameLegacy&&!sameNew)continue;String key=hash(ContractCodec.item(definition.deliveryItem()));long remaining=Math.max(0,contract.goal()-contract.progress());promised.merge(key,remaining,Math::addExact);evidence.add(contract.id()+":"+remaining);}
        Collections.sort(evidence);String fingerprint=hash(String.valueOf(needs.get("fingerprint"))+":"+evidence);var result=new ArrayList<Offer>();for(Object raw:(List<?>)needs.get("materials")){if(!(raw instanceof Map<?,?> item))throw new IllegalArgumentException("Неверная строка материалов");String key=hash(String.valueOf(item.get("item")));var offer=offer(needs,item,promised.getOrDefault(key,0L),fingerprint);if(offer!=null)result.add(offer);}if(result.size()>45)throw new IllegalArgumentException("В смете слишком много материалов");return CompletableFuture.completedFuture(List.copyOf(result));}));}
    @Override public CompletionStage<List<Map<String,Object>>> offers(Player player,String project){return owner(player,()->offered(player,project,null).thenApply(rows->rows.stream().map(Offer::view).toList()));}
    @Override public CompletionStage<Map<String,Object>> quote(Player player,String project,String itemKey){return owner(player,()->{Town town=mayor(player,null);UUID city=town.getUUID();return offered(player,project,null).thenCompose(rows->owner(player,()->{Town current=mayor(player,city);newWork();bank("requestDebit");var offer=rows.stream().filter(r->r.itemKey().equals(itemKey)).findFirst().orElseThrow(()->new IllegalArgumentException("Материал уже обеспечен или условия изменились"));long now=System.currentTimeMillis();var order=new ProcurementOrder(UUID.randomUUID(),city,current.getName(),player.getUniqueId(),player.getName(),offer.project(),offer.level(),offer.title(),offer.fingerprint(),offer.itemKey(),offer.item(),offer.name(),offer.amount(),offer.cents(),offer.duration(),now,now+30_000,"QUOTE",0,"Подтвердите оплату в течение 30 секунд; поставка придёт на общий склад",null,"","");return repository.quote(order).thenCompose(saved->owner(player,()->{mayor(player,city);return CompletableFuture.completedFuture(saved.view());}));}));});}
    @Override public CompletionStage<Map<String,Object>> confirm(Player player,UUID id){return owner(player,()->serial(id,()->repository.get(id).thenCompose(order->owner(player,()->{mayor(player,order.town());if(order.state().equals("QUOTE")){if(!player.getUniqueId().equals(order.actor()))throw new IllegalArgumentException("Эту смету подготовил другой мэр; откройте новую");newWork();return offered(player,order.project(),id).thenCompose(rows->owner(player,()->{mayor(player,order.town());var current=rows.stream().filter(o->o.itemKey().equals(order.itemKey())).findFirst().orElseThrow(()->new IllegalArgumentException("Материал уже обеспечен"));if(!current.fingerprint().equals(order.fingerprint())||current.amount()!=order.amount()||current.cents()!=order.cents()||current.duration()!=order.duration())throw new IllegalArgumentException("Смета изменилась; откройте подтверждение заново");return repository.funding(id).thenCompose(saved->advance(player,saved,true));}));}return advance(player,order,true);}))));}
    private CompletionStage<Map<String,Object>> advance(Player player,ProcurementOrder order,boolean publish){return owner(player,()->{mayor(player,order.town());return switch(order.state()){
        case "FUNDING","REVIEW"->{var proof=bankStatus(order.id());String state=ProcurementRepository.validateBank(order,proof,false);if(state.equals("ABSENT")){yield requestDebit(order).thenCompose(receipt->repository.bank(order.id(),receipt,false)).thenCompose(saved->owner(player,()->{mayor(player,order.town());return CompletableFuture.completedFuture(saved.view());}));}yield repository.bank(order.id(),proof,false).thenCompose(saved->saved.state().equals("FUNDED")&&publish?publish(player,saved):owner(player,()->{mayor(player,saved.town());return CompletableFuture.completedFuture(saved.view());}));}
        case "FUNDED","PUBLISHING"->publish?publish(player,order):CompletableFuture.completedFuture(order.view());
        case "REFUNDING"->refund(player,order);
        default->CompletableFuture.completedFuture(order.view());};});}
    private CompletionStage<Map<String,Object>> publish(Player player,ProcurementOrder order){return owner(player,()->{mayor(player,order.town());var definition=definition(order);contracts.verifyProcurementTarget(order.town(),order.project());return repository.publishing(order.id()).thenCompose(saved->owner(player,()->{mayor(player,saved.town());contracts.verifyProcurementTarget(saved.town(),saved.project());String result=contracts.publishProcurement(saved.id(),saved.town(),definition,saved.started(),saved.actor(),saved.bankReason());return repository.published(saved.id(),player.getUniqueId(),player.getName(),result.equals("SETTLED")).thenCompose(ack->owner(player,()->{reader(player,ack);return CompletableFuture.completedFuture(ack.view());}));}));});}
    private static ContractDefinition definition(ProcurementOrder r){var sample=ContractCodec.item(r.item());return new ContractDefinition(r.template(),(r.name().length()>130?r.name().substring(0,130):r.name())+" для стройки",ContractType.DELIVERY,sample.getType(),0,List.of("Здание: "+r.building()+" • уровень "+r.level(),"Оплачено из городской казны","Поставка на общий склад; условия после оплаты фиксируются"),sample.getType().name(),sample,r.amount(),r.cents()/100.0,r.duration());}
    @Override public CompletionStage<Map<String,Object>> status(Player player,UUID id){return owner(player,()->repository.get(id).thenCompose(order->owner(player,()->{reader(player,order);if(order.state().equals("PUBLISHED")&&contracts.find(order.town(),order.id().toString())==null&&contracts.procurementPublished(order.id()))return repository.published(id,player.getUniqueId(),player.getName(),true).thenCompose(saved->owner(player,()->{reader(player,saved);return CompletableFuture.completedFuture(saved.view());}));if(Set.of("FUNDING","REVIEW").contains(order.state()))return repository.bank(id,bankStatus(id),false).thenCompose(saved->owner(player,()->{reader(player,saved);return CompletableFuture.completedFuture(saved.view());}));if(order.state().equals("REFUNDING"))return repository.bank(id,bankStatus(order.refundId()),true).thenCompose(saved->owner(player,()->{reader(player,saved);return CompletableFuture.completedFuture(saved.view());}));return CompletableFuture.completedFuture(order.view());})));}
    @Override public CompletionStage<Map<String,Object>> cancel(Player player,UUID id){return owner(player,()->serial(id,()->repository.get(id).thenCompose(order->owner(player,()->{mayor(player,order.town());if(contracts.procurementPublished(id))throw new IllegalArgumentException("Заказ уже опубликован; используйте отмену в /t contracts");return repository.cancel(id,player.getUniqueId(),player.getName(),true).thenCompose(saved->saved.state().equals("REFUNDING")?refund(player,saved):owner(player,()->{mayor(player,saved.town());return CompletableFuture.completedFuture(saved.view());}));}))));}
    private CompletionStage<Map<String,Object>> refund(Player player,ProcurementOrder order){return owner(player,()->{mayor(player,order.town());var proof=bankStatus(order.refundId());String state=ProcurementRepository.validateBank(order,proof,true);CompletionStage<Map<String,Object>> response=state.equals("ABSENT")?requestRefund(order):CompletableFuture.completedFuture(proof);return response.thenCompose(receipt->repository.bank(order.id(),receipt,true)).thenCompose(saved->owner(player,()->{reader(player,saved);return CompletableFuture.completedFuture(saved.view());}));});}
    @Override public CompletionStage<List<Map<String,Object>>> requests(Player player,int page){return owner(player,()->{UUID city=mayor(player,null).getUUID();return repository.requests(city,page).thenCompose(rows->owner(player,()->{mayor(player,city);return CompletableFuture.completedFuture(rows.stream().map(ProcurementOrder::view).toList());}));});}
    public synchronized CompletionStage<Void> closeAsync(){if(stopped!=null)return stopped;closing=true;pulse.cancel();for(var future:List.copyOf(pending))reply(future,null,new IllegalStateException("Закупки остановлены; подтверждённые резервы сохранены"));stopped=audit.closeAsync().handle((v,e)->repository.closeAsync().handle((done,sqlError)->{if(e!=null)throw new CompletionException(e);if(sqlError!=null)throw new CompletionException(sqlError);return (Void)null;})).thenCompose(f->f).toCompletableFuture();return stopped;}
}
